'use client';
import * as React from 'react';

import { defaultIcons } from './icons.tsx';
import type { IconMap } from './icons.tsx';

/** Every user-facing string a component renders on its own. Override for i18n. */
export interface HanjiStrings {
  close: string;
  loading: string;
  clear: string;
  showPassword: string;
  hidePassword: string;
  increment: string;
  decrement: string;
  dismiss: string;
  send: string;
  stop: string;
  copy: string;
  copied: string;
  more: string;
  previous: string;
  next: string;
  required: string;
  optional: string;
  /** Prefix for remove buttons: “Remove Jazz”. */
  remove: string;
  /** Read after an external link’s text. */
  opensInNewTab: string;
  skip: string;
  done: string;
  back: string;
  pagination: string;
  /** “3 of 12” */
  countOf: (n: number, total: number) => string;
  /** “Step 2 of 4” (n is 1-based) */
  stepOf: (n: number, total: number) => string;
  /** “All 4 steps done” */
  allStepsDone: (total: number) => string;
  /** Accessible name of an OTP cell after the first: “Character 2 of 6” */
  characterOf: (n: number, total: number) => string;
  /** “Rated 4.6 out of 5 from 2,184 ratings” (value and count are pre-formatted) */
  ratedOutOf: (value: string, max: number, count?: string) => string;
  /** Read once for a reorderable list: how the keyboard twin works. */
  reorderHint: string;
  /** aria-roledescription of a reorderable item. */
  reorderable: string;
  /** “Lifted Low Tide, position 2 of 6. …” */
  reorderLifted: (name: string, n: number, total: number) => string;
  /** “Low Tide, position 3 of 6.” while moving with the keyboard. */
  reorderMoved: (name: string, n: number, total: number) => string;
  /** “Moved Low Tide to position 3 of 6.” */
  reorderDropped: (name: string, n: number, total: number) => string;
  /** “Low Tide put back at position 2.” */
  reorderCancelled: (name: string, n: number) => string;
  /** SwipeActions: name of a row's menu of its swipe actions. */
  moreActions: string;
  /** SwipeActions: the same, for a named row: “More actions for Quarterly numbers”. */
  moreActionsFor: (name: string) => string;
  /** SwipeActions: said after a full swipe commits: “Archive: Quarterly numbers. Done.” */
  swipeActionDone: (action: string, name?: string) => string;
  /** DataTable: the header checkbox. */
  selectAllRows: string;
  /** DataTable: a row's checkbox, read before the row's name: “Select row Mira Okafor”. */
  selectRow: string;
  /** DataTable sort announcement: “Sorted by Amount, descending” · “No longer sorted by Amount”. */
  sortedBy: (column: string, direction: 'ascending' | 'descending' | 'none') => string;
  /** DataTable with no rows and no `empty` content. */
  noRows: string;
  /** Accessible name of the ⌘K dialog. */
  commandPalette: string;
  /** Accessible name of the command palette's search input. */
  commandSearch: string;
  /** Command palette empty state: “No results for “q”” (query may be empty). */
  commandEmpty: (query: string) => string;
  /** Drop zone prompt: “Drop files here”, or “Drop a file here” when it takes one. */
  dropFiles: (multiple: boolean) => string;
  /** The drop zone button that opens the file picker. */
  browseFiles: string;
  /** A file rejected because its type isn't accepted. */
  fileTypeRejected: string;
  /** A file rejected for size: “Over 10 MB” (the limit, formatted). */
  fileTooLarge: (max: string) => string;
  /** A file rejected past the file limit: “Over the 5-file limit”. */
  tooManyFiles: (max: number) => string;
  /** Announced when files land: “2 files added”. */
  filesAdded: (n: number) => string;
  /** A file that finished uploading. */
  uploaded: string;
  /** A failed upload, when the app gives no reason. */
  uploadFailed: string;
  /** Retry a failed upload: “Retry lease.pdf”. */
  retry: string;
  /** Tree: the row shown when a lazy item's children failed to load. */
  treeLoadFailed: string;
  /** Tree: the verb on that row — Enter or a click loads again. */
  treeRetry: string;
  /** Tree: the row inside an open item with no children. */
  treeEmpty: string;
  /** Tree: announced when lazy children arrive: “Archive 2019, 12 items”. */
  treeLoaded: (name: string, count: number) => string;
  /** Tree: announced when they fail: “Couldn’t load Archive 2019”. */
  treeLoadFailedOf: (name: string) => string;
}

export const defaultStrings: HanjiStrings = {
  close: 'Close',
  loading: 'Loading',
  clear: 'Clear',
  showPassword: 'Show password',
  hidePassword: 'Hide password',
  increment: 'Increase',
  decrement: 'Decrease',
  dismiss: 'Dismiss',
  send: 'Send',
  stop: 'Stop generating',
  copy: 'Copy',
  copied: 'Copied',
  more: 'More',
  previous: 'Previous',
  next: 'Next',
  required: 'Required',
  optional: 'Optional',
  remove: 'Remove',
  opensInNewTab: 'opens in a new tab',
  skip: 'Skip',
  done: 'Done',
  back: 'Back',
  pagination: 'Pagination',
  countOf: (n, total) => `${n} of ${total}`,
  stepOf: (n, total) => `Step ${n} of ${total}`,
  allStepsDone: (total) => `All ${total} steps done`,
  characterOf: (n, total) => `Character ${n} of ${total}`,
  ratedOutOf: (value, max, count) =>
    `Rated ${value} out of ${max}${count ? ` from ${count} ratings` : ''}`,
  reorderHint:
    'Reorderable list. Space lifts an item, arrow keys move it, Space drops it, Escape cancels.',
  reorderable: 'reorderable item',
  reorderLifted: (name, n, total) =>
    `Lifted ${name}, position ${n} of ${total}. Arrow keys move it, Space drops it, Escape cancels.`,
  reorderMoved: (name, n, total) => `${name}, position ${n} of ${total}.`,
  reorderDropped: (name, n, total) => `Moved ${name} to position ${n} of ${total}.`,
  reorderCancelled: (name, n) => `${name} put back at position ${n}.`,
  moreActions: 'More actions',
  moreActionsFor: (name) => `More actions for ${name}`,
  swipeActionDone: (action, name) => (name ? `${action}: ${name}. Done.` : `${action}. Done.`),
  selectAllRows: 'Select all rows',
  selectRow: 'Select row',
  sortedBy: (column, direction) =>
    direction === 'none' ? `No longer sorted by ${column}` : `Sorted by ${column}, ${direction}`,
  noRows: 'Nothing to show',
  commandPalette: 'Command palette',
  commandSearch: 'Search commands',
  commandEmpty: (query) => (query ? `No results for “${query}”` : 'No results'),
  dropFiles: (multiple) => (multiple ? 'Drop files here' : 'Drop a file here'),
  browseFiles: 'Browse',
  fileTypeRejected: 'File type not accepted',
  fileTooLarge: (max) => `Over ${max}`,
  tooManyFiles: (max) => (max === 1 ? 'Only one file allowed' : `Over the ${max}-file limit`),
  filesAdded: (n) => (n === 1 ? '1 file added' : `${n} files added`),
  uploaded: 'Uploaded',
  uploadFailed: 'Upload failed',
  retry: 'Retry',
  treeLoadFailed: 'Couldn’t load',
  treeRetry: 'Try again',
  treeEmpty: 'Empty',
  treeLoaded: (name, count) =>
    count === 0 ? `${name} is empty` : `${name}, ${count} ${count === 1 ? 'item' : 'items'}`,
  treeLoadFailedOf: (name) => `Couldn’t load ${name}`,
};

/**
 * Library-wide configuration. Read once per component render from one stable context, so it
 * costs a single context lookup and never causes extra renders.
 */
export interface HanjiConfig {
  /** Drop every hanji class. Components keep behaviour, ARIA and data-attributes. */
  unstyled: boolean;
  /** Extra classes per slot, e.g. `{ Button: 'my-btn', 'Dialog.Popup': 'my-popup' }`. */
  classNames: Readonly<Record<string, string>>;
  /** Default props per slot, e.g. `{ Button: { size: 'sm' } }`. Props passed at the call site win. */
  defaults: Readonly<Record<string, Readonly<Record<string, unknown>>>>;
  /** Icon adapter: replace any built-in glyph with your icon set. */
  icons: IconMap;
  /** User-facing strings. */
  strings: HanjiStrings;
}

const DEFAULT_CONFIG: HanjiConfig = {
  unstyled: false,
  classNames: {},
  defaults: {},
  icons: defaultIcons,
  strings: defaultStrings,
};

const ConfigContext = React.createContext<HanjiConfig>(DEFAULT_CONFIG);

export interface HanjiProviderProps {
  unstyled?: boolean;
  classNames?: Readonly<Record<string, string>>;
  defaults?: Readonly<Record<string, Readonly<Record<string, unknown>>>>;
  icons?: Partial<IconMap>;
  strings?: Partial<HanjiStrings>;
  children?: React.ReactNode;
}

/**
 * Optional. Configure defaults, slot classes, icons and strings for everything below it.
 * Nested providers merge with their parent.
 */
export function HanjiProvider(props: HanjiProviderProps): React.JSX.Element {
  const parent = React.useContext(ConfigContext);
  const { unstyled, classNames, defaults, icons, strings, children } = props;
  const value = React.useMemo<HanjiConfig>(
    () => ({
      unstyled: unstyled ?? parent.unstyled,
      classNames: classNames ? { ...parent.classNames, ...classNames } : parent.classNames,
      defaults: defaults ? mergeDefaults(parent.defaults, defaults) : parent.defaults,
      icons: icons ? ({ ...parent.icons, ...icons } as IconMap) : parent.icons,
      strings: strings ? { ...parent.strings, ...strings } : parent.strings,
    }),
    [parent, unstyled, classNames, defaults, icons, strings],
  );
  return <ConfigContext.Provider value={value}>{children}</ConfigContext.Provider>;
}

function mergeDefaults(
  a: HanjiConfig['defaults'],
  b: HanjiConfig['defaults'],
): HanjiConfig['defaults'] {
  const out: Record<string, Readonly<Record<string, unknown>>> = { ...a };
  for (const [k, v] of Object.entries(b)) out[k] = { ...a[k], ...v };
  return out;
}

/** The nearest configuration. */
export function useHanjiConfig(): HanjiConfig {
  return React.useContext(ConfigContext);
}

'use client';
import * as React from 'react';

/** A time token (`180ms` or `.18s`) read from computed style, in ms. */
export function msVar(cs: CSSStyleDeclaration, name: string, fallback: number): number {
  const v = cs.getPropertyValue(name).trim();
  const n = v.endsWith('ms') ? Number.parseFloat(v) : Number.parseFloat(v) * 1000;
  return Number.isFinite(n) && n >= 0 ? n : fallback;
}

/**
 * FLIP for a wrapping row (chips, attachments): when a child changes size or leaves, its
 * neighbours glide to their new place on the clamped snappy spring — `translate` only, never a
 * bounce. If the row gains or loses a line, its height glides with them so whatever sits below
 * follows instead of jumping. Layout positions come from offsetLeft/Top, which ignore running
 * transforms.
 *
 * @param attributes Child attributes whose change may move the row (e.g. `data-leaving`).
 */
export function useFlip(
  ref: React.RefObject<HTMLElement | null>,
  attributes: readonly string[] = [],
): void {
  const filter = attributes.join(' ');
  React.useLayoutEffect(() => {
    const host = ref.current;
    if (!host || typeof MutationObserver === 'undefined') return undefined;
    let places = new Map<Element, { x: number; y: number }>();
    let height = host.offsetHeight;
    let grow: Animation | null = null;
    const snapshot = (): void => {
      height = host.offsetHeight;
      places = new Map();
      for (const c of host.children) {
        if (c instanceof HTMLElement) places.set(c, { x: c.offsetLeft, y: c.offsetTop });
      }
    };
    snapshot();
    const mo = new MutationObserver(() => {
      const cs = getComputedStyle(host);
      const duration = msVar(cs, '--hj-dur-snappy-settle', 180);
      const easing = cs.getPropertyValue('--hj-ease-snappy-settle').trim() || 'ease-out';
      for (const c of host.children) {
        if (!(c instanceof HTMLElement) || typeof c.animate !== 'function') continue;
        const before = places.get(c);
        if (!before) continue;
        const dx = before.x - c.offsetLeft;
        const dy = before.y - c.offsetTop;
        if (Math.abs(dx) < 0.5 && Math.abs(dy) < 0.5) continue;
        c.animate([{ translate: `${dx}px ${dy}px` }, { translate: '0px 0px' }], {
          duration,
          easing,
        });
      }
      grow?.cancel();
      const next = host.offsetHeight;
      if (Math.abs(next - height) >= 0.5 && typeof host.animate === 'function') {
        grow = host.animate([{ height: `${height}px` }, { height: `${next}px` }], {
          duration,
          easing,
        });
      }
      snapshot();
    });
    mo.observe(host, {
      childList: true,
      subtree: filter !== '',
      ...(filter ? { attributes: true, attributeFilter: filter.split(' ') } : {}),
    });
    const ro = typeof ResizeObserver === 'undefined' ? null : new ResizeObserver(snapshot);
    ro?.observe(host);
    return () => {
      mo.disconnect();
      ro?.disconnect();
    };
  }, [ref, filter]);
}

'use client';
import * as React from 'react';

import { useHanjiConfig } from './config.tsx';
import type { IconName } from './icons.tsx';

export interface IconProps extends Omit<React.ComponentProps<'span'>, 'children'> {
  /** A glyph from the icon adapter (`HanjiProvider icons`). */
  name: IconName;
  /** Size in px; the glyph scales with font-size. @default 20 */
  size?: number;
  /** Accessible label. Omit for decorative icons (the default). */
  label?: string;
}

/** Renders a glyph through the icon adapter. Decorative unless `label` is given. */
export function Icon({
  name,
  size = 20,
  label,
  className,
  style,
  ...rest
}: IconProps): React.JSX.Element {
  const config = useHanjiConfig();
  const sized = React.useMemo(
    () => (size === 20 && !style ? undefined : { fontSize: size, ...style }),
    [size, style],
  );
  return (
    <span
      className={config.unstyled ? className : className ? `hj-icon ${className}` : 'hj-icon'}
      style={sized}
      role={label ? 'img' : undefined}
      aria-label={label}
      aria-hidden={label ? undefined : true}
      {...rest}
    >
      {config.icons[name]}
    </span>
  );
}

/**
 * The agent-readable description of a component. Every component folder has a `*.meta.ts`
 * built from these types; `scripts/build-ai.ts` turns them into `manifest.json`, `llms.txt`,
 * the MCP server's index and the source registry.
 *
 * Meta files import component prop types with `import type`, so `props<OwnProps>()` is
 * exhaustive: an undocumented prop, or a documented prop that doesn't exist, fails typecheck.
 */

export type Category =
  | 'foundation'
  | 'atoms'
  | 'controls'
  | 'surfaces'
  | 'navigation'
  | 'data'
  | 'ai';

export interface PropDoc {
  /** The type as a reader should see it, e.g. `'primary' | 'ink' | 'secondary'`. */
  type: string;
  default?: string;
  description: string;
}

export interface PartMeta {
  /** As used in JSX: `Root`, `Popup`, or the component's own name for single-part components. */
  name: string;
  /** The element rendered by default. */
  element: string;
  description: string;
  /** The Base UI part this wraps, e.g. `Dialog.Popup`. Its props are accepted too. */
  base?: string;
  /** Props hanji adds on top of Base UI's. */
  props?: Readonly<Record<string, PropDoc>>;
  /** Slot name for `HanjiProvider` classNames/defaults. */
  slot: string;
  /** hanji's class on this part. */
  className: string;
  /** Styling hooks: data-attributes set on this part. */
  dataAttributes?: Readonly<Record<string, string>>;
  /** Per-part CSS custom properties consumers may set (on the part or any ancestor). */
  cssVars?: Readonly<Record<string, string>>;
}

export interface ExampleMeta {
  /** File in the component's `examples/` folder, without extension. */
  file: string;
  title: string;
  description: string;
}

export interface ComponentMeta {
  name: string;
  /** kebab-case; folder name and registry id. */
  slug: string;
  category: Category;
  /** `new` = not in hanji (React Native); `stable` = ported. */
  status: 'stable' | 'new' | 'beta';
  /** One sentence: what it is for. */
  description: string;
  whenToUse: readonly string[];
  whenNotToUse: readonly string[];
  /** Import line(s), e.g. `import { Dialog } from '@hanji/react'`. */
  import: string;
  parts: readonly PartMeta[];
  examples: readonly ExampleMeta[];
  accessibility: readonly string[];
  /** The motion and why. */
  motion?: string;
  /** Tokens the component reads (without the `--hj-` prefix). */
  tokens: readonly string[];
  related: readonly string[];
  /** Base UI doc this builds on, e.g. `dialog` → node_modules/@base-ui/react/docs/react/components/dialog.md */
  baseUi?: string;
}

/** Identity function that type-checks a component's meta. */
export function defineMeta(meta: ComponentMeta): ComponentMeta {
  return meta;
}

/**
 * Exhaustive prop docs for a part's own props: `props<ButtonOwnProps>({ variant: {...}, … })`.
 * Missing or extra keys are type errors.
 */
export function props<P>(docs: { readonly [K in keyof Required<P>]: PropDoc }): Readonly<
  Record<string, PropDoc>
> {
  return docs as Readonly<Record<string, PropDoc>>;
}

'use client';
import { REDUCED_SPRING, springs } from '@hanji/tokens';
import type { Spring, SpringName } from '@hanji/tokens';
import * as React from 'react';

/**
 * Most hanji motion is CSS: springs are compiled to `linear()` easings at build time and run on
 * the compositor with zero JavaScript. This module is for the few values a finger drives
 * (drag, swipe, scrub), where the spring must be interruptible and keep its velocity.
 */

export interface SpringOptions {
  spring?: SpringName | Spring;
  /** Stop at the first crossing (hanji `settle()`): use whenever completion gates state. */
  clamp?: boolean;
  /** Ignore the reduced-motion policy (only for visualising springs). */
  ignorePolicy?: boolean;
  onUpdate: (value: number, velocity: number) => void;
  onRest?: (value: number) => void;
}

/** True when the nearest `data-hj-motion` or the system asks for reduced motion. */
export function prefersReducedMotion(el?: Element | null): boolean {
  const scoped = el?.closest('[data-hj-motion]')?.getAttribute('data-hj-motion');
  if (scoped === 'reduced') return true;
  if (scoped === 'full') return false;
  return typeof matchMedia === 'function' && matchMedia('(prefers-reduced-motion: reduce)').matches;
}

/**
 * An interruptible spring on one number. Retargeting keeps the current velocity, so a flick
 * that reverses mid-flight never jumps. Integrates in 1 ms steps; one rAF loop, released at rest.
 */
export class SpringValue {
  x: number;
  v = 0;
  private target: number;
  private raf = 0;
  private last = 0;
  private eps = 1e-3;
  private o: SpringOptions;
  reduced = false;

  constructor(value: number, options: SpringOptions) {
    this.x = value;
    this.target = value;
    this.o = options;
  }

  private cfg(): Spring {
    if (this.reduced && !this.o.ignorePolicy) return REDUCED_SPRING;
    const s = this.o.spring ?? 'snappy';
    return typeof s === 'string' ? springs[s] : s;
  }

  /** Replace options (callbacks, spring, clamp) without interrupting the motion. */
  configure(options: Partial<SpringOptions>): this {
    this.o = { ...this.o, ...options };
    return this;
  }

  to(target: number, velocity?: number): this {
    this.target = target;
    if (velocity !== undefined) this.v = velocity;
    this.eps = Math.max(Math.abs(target - this.x), 1) * 1e-3;
    if (!this.raf) {
      this.last = performance.now();
      this.raf = requestAnimationFrame(this.frame);
    }
    return this;
  }

  set(value: number): this {
    this.stop();
    this.x = this.target = value;
    this.v = 0;
    this.o.onUpdate(value, 0);
    return this;
  }

  stop(): void {
    if (this.raf) cancelAnimationFrame(this.raf);
    this.raf = 0;
  }

  private frame = (now: number): void => {
    const { stiffness: k, damping: c, mass: m } = this.cfg();
    const clamp = this.o.clamp || (this.reduced && !this.o.ignorePolicy);
    const ms = Math.min(48, Math.max(1, now - this.last));
    this.last = now;
    const from = this.x;
    for (let i = 0; i < ms; i++) {
      const a = (-k * (this.x - this.target) - c * this.v) / m;
      this.v += a / 1000;
      this.x += this.v / 1000;
      if (clamp && (from - this.target) * (this.x - this.target) <= 0) {
        this.x = this.target;
        this.v = 0;
        break;
      }
    }
    const rest = Math.abs(this.x - this.target) < this.eps && Math.abs(this.v) < this.eps * 20;
    if (rest) {
      this.x = this.target;
      this.v = 0;
    }
    this.o.onUpdate(this.x, this.v);
    if (rest) {
      this.raf = 0;
      this.o.onRest?.(this.x);
      return;
    }
    this.raf = requestAnimationFrame(this.frame);
  };
}

/**
 * A spring whose updates go straight to the DOM (no React state, no re-renders).
 *
 * @example
 * const ref = useRef<HTMLDivElement>(null);
 * const y = useSpring(0, { spring: 'gentle', onUpdate: (v) => { ref.current!.style.transform = `translateY(${v}px)`; } });
 * y.to(320, flickVelocity);
 */
export function useSpring(initial: number, options: SpringOptions): SpringValue {
  const [spring] = React.useState(() => new SpringValue(initial, options));
  // Latest callbacks without re-creating the spring (and without touching refs during render).
  React.useLayoutEffect(() => {
    spring.configure(options);
  });
  React.useEffect(() => () => spring.stop(), [spring]);
  return spring;
}

'use client';
import { useRender } from '@base-ui/react/use-render';
import * as React from 'react';

import { useHanjiConfig } from './config.tsx';
import { cls, withDefaults } from './slot.ts';
import type { ClassName } from './slot.ts';

/** A Base UI part with hanji's class, slot defaults and slot classes applied. */
export type HanjiPart<C extends React.ElementType> = (
  props: React.ComponentProps<C>,
) => React.ReactElement;

/**
 * Wrap a Base UI part that needs no props of its own. Accepts every Base UI prop (render,
 * className as a function of state, style, …) and adds hanji's class for the slot.
 *
 * @example export const Title: HanjiPart<typeof Base.Title> = part(Base.Title, 'Dialog.Title', 'hj-dialog-title');
 */
export function part<C extends React.ElementType>(
  Base: C,
  slot: string,
  base: string,
): HanjiPart<C> {
  function HanjiPartComponent(props: React.ComponentProps<C>): React.ReactElement {
    const config = useHanjiConfig();
    const p = withDefaults(config, slot, props) as React.ComponentProps<C> & {
      className?: ClassName<unknown>;
    };
    const Component = Base as React.ElementType;
    return <Component {...p} className={cls(config, slot, base, p.className)} />;
  }
  HanjiPartComponent.displayName = slot;
  return HanjiPartComponent;
}

/** Props for a hanji-only layout part (no Base UI behaviour), with Base UI's `render` prop. */
export type ElementPartProps<T extends keyof React.JSX.IntrinsicElements> = Omit<
  React.ComponentProps<T>,
  'className'
> & {
  className?: string;
  render?: useRender.RenderProp;
};

/**
 * A hanji-only part that renders a plain element (header, actions row…), composable via
 * `render` like every Base UI part.
 */
export function elementPart<T extends keyof React.JSX.IntrinsicElements>(
  tag: T,
  slot: string,
  base: string,
): (props: ElementPartProps<T>) => React.ReactElement {
  function HanjiElementPart(props: ElementPartProps<T>): React.ReactElement {
    const config = useHanjiConfig();
    const { render, className, ...rest } = withDefaults(config, slot, props);
    return useRender({
      render,
      defaultTagName: tag,
      props: { ...rest, className: cls(config, slot, base, className) as string | undefined },
    });
  }
  HanjiElementPart.displayName = slot;
  return HanjiElementPart;
}

import type { HanjiConfig } from './config.tsx';

/** Base UI's className: a string, or a function of the part's state. */
export type ClassName<State> = string | ((state: State) => string | undefined) | undefined;

const join = (a: string, b: string | undefined): string => (b ? (a ? `${a} ${b}` : b) : a);

/**
 * Resolve a part's class: hanji's class (unless unstyled) + the provider's slot class + the
 * call site's class. Keeps Base UI's function form when the caller passed a function.
 *
 * @param slot  the slot name used by `HanjiProvider.classNames`, e.g. `'Dialog.Popup'`
 * @param base  hanji's class for the part, e.g. `'hj-dialog-popup'`
 */
export function cls<State>(
  config: HanjiConfig,
  slot: string,
  base: string,
  className: ClassName<State>,
): ClassName<State> {
  const own = join(config.unstyled ? '' : base, config.classNames[slot]);
  if (typeof className === 'function') {
    return (state: State): string => join(own, className(state) ?? undefined);
  }
  return join(own, className) || undefined;
}

/**
 * Merge provider defaults under call-site props. Returns the same object when the slot has no
 * defaults, so the common path allocates nothing.
 */
export function withDefaults<P extends object>(config: HanjiConfig, slot: string, props: P): P {
  const d = config.defaults[slot];
  return d ? ({ ...d, ...props } as P) : props;
}

/** `data-*` boolean: present when true, absent otherwise (so CSS can use `[data-x]`). */
export function flag(value: boolean | undefined): '' | undefined {
  return value ? '' : undefined;
}

'use client';
import { useRender } from '@base-ui/react/use-render';
import { createTheme } from '@hanji/tokens';
import type { HanjiTheme, ThemeInput } from '@hanji/tokens';
import * as React from 'react';

interface ThemeScopeValue {
  attributes: HanjiTheme['attributes'];
  style: React.CSSProperties | undefined;
}

const ThemeScopeContext = React.createContext<ThemeScopeValue | null>(null);

export interface ThemeProps extends ThemeInput, Omit<React.ComponentProps<'div'>, 'style'> {
  /** A theme from `createTheme()`. Individual fields (paper, accent…) override it. */
  theme?: HanjiTheme;
  /** Paint the paper's background and ink on this element. Off: the wrapper is `display: contents`. */
  surface?: boolean;
  style?: React.CSSProperties;
  /** Render a different element, or compose with your own component. */
  render?: useRender.RenderProp;
}

/**
 * Themes a subtree. Every hanji component below it — including popups portalled to `<body>` —
 * reads this paper, accent, density and motion policy.
 *
 * @example
 * <Theme paper="ink" accent="cobalt" density="compact">…</Theme>
 */
export function Theme(props: ThemeProps): React.ReactElement {
  const {
    theme,
    paper,
    accent,
    density,
    motion,
    radius,
    smoothing,
    fonts,
    colors,
    springs,
    surface,
    style,
    render,
    className,
    ...rest
  } = props;
  const input: ThemeInput = {
    paper,
    accent,
    density,
    motion,
    radius,
    smoothing,
    fonts,
    colors,
    springs,
  };
  const key = JSON.stringify(input);
  // Keyed by the serialised input: inline objects at the call site don't re-resolve the theme.
  // oxlint-disable-next-line react/exhaustive-deps
  const own = React.useMemo(() => createTheme(input), [key]);
  const resolved = React.useMemo<HanjiTheme>(
    () =>
      theme
        ? {
            ...theme,
            attributes: { ...theme.attributes, ...own.attributes },
            vars: { ...theme.vars, ...own.vars },
          }
        : own,
    [theme, own],
  );

  const vars = resolved.vars as React.CSSProperties;
  const hasVars = Object.keys(vars).length > 0;
  const mergedStyle = hasVars || style ? { ...vars, ...style } : undefined;
  const scope = React.useMemo<ThemeScopeValue>(
    () => ({ attributes: resolved.attributes, style: hasVars ? vars : undefined }),
    [resolved, hasVars, vars],
  );

  const element = useRender({
    render,
    defaultTagName: 'div',
    props: {
      ...resolved.attributes,
      ...rest,
      'data-hj-surface': surface ? '' : undefined,
      className: className ? `hj-theme ${className}` : 'hj-theme',
      style: mergedStyle,
    },
  });
  return <ThemeScopeContext.Provider value={scope}>{element}</ThemeScopeContext.Provider>;
}

/**
 * Wraps portalled content in the nearest Theme's attributes, so a popup opened inside
 * `<Theme paper="ink">` is drawn in ink even though it lives under `<body>`.
 */
export function ThemeScope({ children }: { children?: React.ReactNode }): React.ReactNode {
  const scope = React.useContext(ThemeScopeContext);
  if (!scope) return children;
  return (
    <div className="hj-theme" {...scope.attributes} style={scope.style}>
      {children}
    </div>
  );
}

/** The nearest Theme's resolved attributes, or null outside any Theme. */
export function useThemeScope(): ThemeScopeValue | null {
  return React.useContext(ThemeScopeContext);
}

'use client';
import { useHanjiConfig } from './config.tsx';
import type { HanjiConfig } from './config.tsx';
import { withDefaults } from './slot.ts';

/**
 * Config plus provider defaults merged under the call-site props, in one hook. Being a hook, its
 * result is treated as immutable by the React Compiler, so it can feed `useMemo` safely.
 *
 * @example const [config, { size = 'md', className, ...rest }] = useSlot('Chip', props);
 */
export function useSlot<P extends object>(slot: string, props: P): [HanjiConfig, P] {
  const config = useHanjiConfig();
  return [config, withDefaults(config, slot, props)];
}

/*
 * hanji base: only what every component relies on. Scoped to hanji's own elements — the
 * library never restyles your app's elements.
 */
@layer hj.base {
  :where([class^='hj-'], [class*=' hj-']),
  :where([class^='hj-'], [class*=' hj-'])::before,
  :where([class^='hj-'], [class*=' hj-'])::after {
    box-sizing: border-box;
  }

  .hj-theme:not([data-hj-surface]) {
    display: contents;
  }
  .hj-theme[data-hj-surface] {
    background: var(--hj-bg);
    color: var(--hj-fg);
    font-family: var(--hj-font-sans);
  }

  .hj-icon {
    display: inline-flex;
    flex: none;
    width: 1em;
    height: 1em;
    font-size: 20px;
    line-height: 0;
  }
  .hj-icon > svg {
    width: 100%;
    height: 100%;
  }

  /* Shared keyframes. Components reference them through the motion-policy tokens. */
  @keyframes hj-spin {
    to {
      transform: rotate(360deg);
    }
  }
  @keyframes hj-pulse {
    from {
      opacity: 0.55;
    }
    to {
      opacity: 0.9;
    }
  }
  @keyframes hj-fade-in {
    from {
      opacity: 0;
    }
  }

  /* Keyboard focus: one ring, the accent, never on pointer focus. */
  :where([class^='hj-'], [class*=' hj-']):focus-visible {
    outline: 2px solid var(--hj-focus);
    outline-offset: 2px;
  }
}

/* Opt-in helpers. Lowest-priority layer after components; your own CSS still wins. */
@layer hj.utilities {
  .hj-text-hero,
  .hj-text-display,
  .hj-text-title,
  .hj-text-heading,
  .hj-text-subheading,
  .hj-text-body,
  .hj-text-sub,
  .hj-text-label,
  .hj-text-eyebrow,
  .hj-text-mono {
    margin: 0;
  }
  .hj-text-hero {
    font: var(--hj-type-hero);
    letter-spacing: var(--hj-tracking-hero);
    font-variant-numeric: tabular-nums;
  }
  .hj-text-display {
    font: var(--hj-type-display);
    letter-spacing: var(--hj-tracking-display);
  }
  .hj-text-title {
    font: var(--hj-type-title);
    letter-spacing: var(--hj-tracking-title);
  }
  .hj-text-heading {
    font: var(--hj-type-heading);
    letter-spacing: var(--hj-tracking-heading);
  }
  .hj-text-subheading {
    font: var(--hj-type-subheading);
    letter-spacing: var(--hj-tracking-subheading);
  }
  .hj-text-body {
    font: var(--hj-type-body);
    letter-spacing: var(--hj-tracking-body);
  }
  .hj-text-sub {
    font: var(--hj-type-sub);
    letter-spacing: var(--hj-tracking-sub);
  }
  .hj-text-label {
    font: var(--hj-type-label);
    letter-spacing: var(--hj-tracking-label);
  }
  .hj-text-eyebrow {
    font: var(--hj-type-eyebrow);
    letter-spacing: var(--hj-tracking-eyebrow);
    text-transform: uppercase;
  }
  .hj-text-mono {
    font: var(--hj-type-mono);
    letter-spacing: var(--hj-tracking-mono);
    font-variant-numeric: tabular-nums;
  }
  .hj-tone-dim {
    color: var(--hj-fg-dim);
  }
  .hj-tone-mute {
    color: var(--hj-fg-mute);
  }
  .hj-tone-accent {
    color: var(--hj-accent);
  }
  .hj-tabular {
    font-variant-numeric: tabular-nums;
  }

  .hj-sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    margin: -1px;
    padding: 0;
    overflow: hidden;
    clip: rect(0 0 0 0);
    white-space: nowrap;
    border: 0;
  }

  /* Staggered entrance for a list: one clock, 24 ms a row, capped at 10. Set --hj-i per child. */
  .hj-stagger > * {
    animation: hj-rise var(--hj-dur-gentle-settle) var(--hj-ease-gentle-settle) both;
    animation-delay: calc(min(var(--hj-i, 0), var(--hj-stagger-cap)) * var(--hj-stagger));
  }
  @keyframes hj-rise {
    from {
      opacity: 0;
      transform: translateY(calc(var(--hj-rise) * var(--hj-travel)));
    }
  }
}
